- [ ] Add the function after `reply` (before `module.exports`):

  ```js
  // The customer's rating of a resolved ticket. One rating per ticket; the score snapshots
  // the agent under owner_id now, ahead of the ticket row's own owner_id rename.
  function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
    const t = getMyTicket(store, customer, id);
    if (!t) return null;
    if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('score must be a whole number from 1 to 5');
    if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
    if (store.getRating(id)) throw new Error('this ticket already has a rating');
    const rating = { owner_id: t.assignee_id, score, rated_at: now.toISOString() };
    store.addRating(id, rating);
    if (t.assignee_id && score <= 2) notifyAgent(store, t.assignee_id, { type: 'ticket_rated_low', ticketId: id, score });
    return { ticket_id: id, ...rating };
  }
  ```

