  ```js
  'use strict';
  // Nightly. Writes exports/rating-summary.json: per agent, how many ratings their tickets
  // received in the past seven days and the average score.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function ratingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const byAgent = new Map();
    for (const r of store.listRatings()) {
      if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
      if (!r.owner_id) continue;
      const agent = byAgent.get(r.owner_id) || { count: 0, total: 0 };
      agent.count += 1;
      agent.total += r.score;
      byAgent.set(r.owner_id, agent);
    }
    const rows = [...byAgent.entries()].map(([owner_id, { count, total }]) => ({
      owner_id,
      ratings: count,
      average: Math.round((total / count) * 100) / 100,
    }));
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'rating-summary.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows: rows.length };
  }

  module.exports = { ratingSummary, WINDOW_DAYS };
  ```

